def find_index(nums, target):

    """
    This function takes a list of numbers 'nums' and a target number 'target' as input.
    It returns the index of the target number if it exists in the list, otherwise it returns -1.
    """

### Solution:


    # Check if nums is empty
    if not nums:
        return -1

    # Perform binary search on the sorted list of numbers
    left = 0
    right = len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid

        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

