def is_perfect_square(n):
    """Checks if a given number is a perfect square or not."""

### Solution:

    if n < 1:
        return False
    left, right = 1, n
    while left <= right:
        mid = (left + right) // 2
        if mid * mid == n:
            return True
        elif mid * mid < n:
            left = mid + 1
        else:
            right = mid - 1
    return False

